+import type { SessionEvent } from '../types.ts';
+
+// The slop guard reads a run's own changes and flags shortcuts that make work look done. It is advisory:
+// findings are a reminder and evidence, never a refusal.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; text?: string };
+
+const DOC = /\.(md|mdx|markdown|txt|rst|adoc)$/i;
+const TEST_PATH = /(^|\/)(tests?|__tests__)\/|(\.|_)(test|spec)\.[^/]+$|(^|\/)test_[^/]*$/;
+const ASSERT = /\bassert|\bexpect\(|\.to[A-Z]\w*\(|\bshould\b/;
+const SKIP = /\.skip\(|\bx(it|describe|test)\(|\.Skip\(|@pytest\.mark\.skip|\bpytest\.skip\(|\bit\.todo\(|@Ignore\b/;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|nocheck)\b|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint\b/],
+  ['swallowed-error', /\bcatch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/],
+  ['type-escape', /\bas any\b/],
+  ['stub', /\bNotImplementedError\b|\bnot implemented\b|\btodo!\(|\bunimplemented!\(/i],
+];
+
+const lines = (s: string) => s.split('\n');
+const count = (xs: string[], re: RegExp) => xs.filter((l) => re.test(l)).length;
+
+// Reads a `git diff -U0` style patch. Only hunk lines count, so `+++`/`---` headers never leak in as content.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.+ b\/(.+)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Changes made by edit and write calls, for runs without snapshots. Only completed calls count.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const done = new Set(events.flatMap((e) => (e.kind === 'tool_result' && e.status === 'completed' ? [e.callId] : [])));
+  return events.flatMap((e): FileChange[] => {
+    if (e.kind !== 'tool_intent' || !done.has(e.callId)) return [];
+    const path = String(e.input.path ?? '');
+    if (e.tool === 'write') return [{ path, added: lines(String(e.input.content ?? '')), removed: [], deleted: false }];
+    if (e.tool !== 'edit' || !Array.isArray(e.input.edits)) return [];
+    const edits = e.input.edits as { old_text: string; new_text: string }[];
+    return [{ path, added: edits.flatMap((x) => lines(x.new_text)), removed: edits.flatMap((x) => lines(x.old_text)), deleted: false }];
+  });
+}
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  return changes.flatMap((c): Finding[] => {
+    if (DOC.test(c.path)) return [];
+    const test = TEST_PATH.test(c.path);
+    const out: Finding[] = [];
+    if (test && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (test && !c.deleted && count(c.removed, ASSERT) > count(c.added, ASSERT)) out.push({ rule: 'test-weakened', path: c.path });
+    if (test && !c.deleted && count(c.added, SKIP) > 0) out.push({ rule: 'test-skipped', path: c.path });
+    for (const l of c.added) {
+      const text = l.trim().slice(0, 120);
+      for (const [rule, re] of LINE_RULES) if (re.test(l)) out.push({ rule, path: c.path, text });
+    }
+    return out;
+  });
+}
+
+export const flagText = (f: Finding) => (f.text ? `${f.rule} ${f.path}: ${f.text}` : `${f.rule} ${f.path}`);
