+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('exactly 10 units get the 5% bulk tier', () => {
+    // 10 mugs = 4500; 5% off = 225 -> 4275; shipping 800; tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 10]]))).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('lines of the same sku are merged before bulk pricing', () => {
+    // 5 + 5 mugs is 10 units: same as 10 mugs above
+    expect(totals(cart('US', [['MUG', 5], ['MUG', 5]]))).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('exactly 50 units get the 10% bulk tier and free US shipping', () => {
+    // 50 pens = 6000; 10% off = 600 -> 5400 >= 5000 so shipping 0; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('shipping threshold uses the subtotal after the coupon', () => {
+    // 4 caps + 2 pens = 5040 >= 5000, but FLAT5 takes it to 4540 < 5000, so shipping 800
+    // tax 7% of 5340 = 373.8 -> 374
+    expect(totals(cart('US', [['CAP', 4], ['PEN', 2]], 'FLAT5'))).toMatchObject({ subtotal: 5040, coupon: 500, shipping: 800, tax: 374, total: 5714 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 3 caps + 4 pens = 4080 >= 4000 so shipping 0; tax 20% of 4080 = 816
+    expect(totals(cart('UK', [['CAP', 3], ['PEN', 4]]))).toMatchObject({ subtotal: 4080, shipping: 0, tax: 816, total: 4896 });
+  });
+});

