+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+import { bulkDiscount } from '../src/pricing/discounts/bulk.ts';
+import { REGIONS } from '../src/pricing/regions.ts';
+
+describe('pricing rules from README', () => {
+  test('bulk tiers start at 10 and 50 units, inclusive', () => {
+    expect(bulkDiscount(9, 1000)).toBe(0);
+    expect(bulkDiscount(10, 1000)).toBe(50);
+    expect(bulkDiscount(49, 1000)).toBe(50);
+    expect(bulkDiscount(50, 1000)).toBe(100);
+  });
+
+  test('UK free shipping threshold is 4000', () => {
+    expect(REGIONS.UK.freeShippingFrom).toBe(4000);
+  });
+
+  test('lines of the same SKU are merged before the bulk tier is chosen', () => {
+    // MUG 450: 6 + 5 = 11 units = 4950; 5% off = 248 (247.5 rounds up); discounted subtotal 4702 < 5000 so shipping 800;
+    // tax 7% of 5502 = 385.14 -> 385; total 4702 + 800 + 385 = 5887
+    const t = totals(cart('US', [['MUG', 6], ['MUG', 5]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t).toMatchObject({ subtotal: 4702, shipping: 800, tax: 385, total: 5887 });
+  });
+
+  test('shipping threshold is judged on the discounted subtotal', () => {
+    // BAG 2200: 2 bags = 4400 >= 4000, but SAVE10 leaves 3960 < 4000, so UK shipping 700 is charged.
+    // tax 20% of 4660 = 932; total 3960 + 700 + 932 = 5592
+    const t = totals(cart('UK', [['BAG', 2]], 'SAVE10'));
+    expect(t).toMatchObject({ subtotal: 4400, coupon: 440, shipping: 700, tax: 932, total: 5592 });
+  });
+});

