+  const part = /\s*(\d+(?:\.\d+)?)(ms|d|h|m|s)/y;
+  let total = 0;
+  let pos = 0;
+  let count = 0;
+  while (pos < s.length) {
+    part.lastIndex = pos;
+    const m = part.exec(s);
+    if (!m) throw new Error(`invalid duration: "${text}"`);
+    total += Number(m[1]) * UNIT_MS[m[2]];
+    pos = part.lastIndex;
+    count++;
+  }
+  if (count === 0) throw new Error(`invalid duration: "${text}"`);
+  return Math.round(total);
 }

 export function formatDuration(ms: number): string {
-  throw new Error('not implemented');
+  if (ms < 0) throw new Error(`negative duration: ${ms}`);
+  let rest = Math.round(ms);
+  if (rest === 0) return '0s';
+  let out = '';
+  for (const unit of ['d', 'h', 'm', 's', 'ms']) {
+    const n = Math.floor(rest / UNIT_MS[unit]);
+    if (n > 0) out += `${n}${unit}`;
+    rest -= n * UNIT_MS[unit];
+  }
+  return out;
 }
